test("facturasVigentes: devuelve solo las emitidas sin modificar la lista", () => {
  const items = [{ cantidad: 1, precioUnitarioCentavos: 1000 }];
  const a = emitirFactura({ numero: 1, nit: "1023456", razonSocial: "A", items });
  const b = { ...emitirFactura({ numero: 2, nit: "1023456", razonSocial: "B", items }), estado: "anulada" };
  const c = emitirFactura({ numero: 3, nit: "1023456", razonSocial: "C", items });
  const lista = [a, b, c];
  const vigentes = facturasVigentes(lista);
  assert.deepEqual(vigentes, [a, c]);
  assert.notEqual(vigentes, lista);
  assert.deepEqual(lista, [a, b, c]);
  assert.deepEqual(facturasVigentes([]), []);
  assert.throws(() => facturasVigentes(null), TypeError);
});
